// Markenporträts (für /marken und /marken/[name]) – t = Text (Absätze mit Leerzeile), f = ideal für, x = Steckbrief
// Fakten aus Firmenangaben und Fachpresse (Stand 11/2026); unsichere Angaben sind bewusst weggelassen.
export type BrandFacts = { gegruendet?: string; sitz?: string; mitarbeiter?: string; gehoert?: string };
export const BRAND_TEXTS: Record<string, { t: string; f: string[]; x: BrandFacts }> = {
  "Anthem": {"t": "Anthem steht für nachhaltige Basics aus Bio-Baumwolle mit modernem, leicht entspanntem Schnitt. T-Shirts, Heavyweight-Shirts, Sweatshirts, Hoodies und Jogger kommen in ruhigen, gut kombinierbaren Farben – vieles ist zusätzlich als vegan gekennzeichnet.\n\nDie Teile sind ausdrücklich als „Leinwand“ für Druck und Stick gedacht und eignen sich für alle, die ihr Logo bewusst auf ein nachhaltiges Produkt setzen möchten – vom Start-up-Merch bis zur Team-Kollektion.", "f": ["Nachhaltige Teamwear", "Start-ups", "Merch"], "x": {}},
  "ARTG": {"t": "ARTG bringt Wohlfühl-Textilien ins Sortiment: kuschelige Decken, Sherpa-Fleece, Strickdecken und Kinderdecken wie die Linien „Babiezz“ und „Originalzz“. Die Produkte sind für den Alltag zu Hause, im Auto oder auf der Tribüne gedacht.\n\nMit eingesticktem Logo oder Namen werden die Decken zu Geschenken, die lange in Gebrauch bleiben – beliebt bei Kundengeschenken zum Jahresende, als Hotel-Accessoire oder als Fanartikel im Verein.", "f": ["Kundengeschenke", "Hotels", "Fanartikel"], "x": {}},
  "Asquith & Fox": {"t": "Asquith & Fox ist eine britische Marke, die Basics mit modischem Anspruch verbindet. Herzstück ist das klassische Poloshirt, das es in zwei Passformen, bis Größe 5XL und in bis zu 45 Farben gibt. Dazu kommen Hemden, Strick, Chinos, Sweatshirts und Accessoires.\n\nDie Kollektion richtet sich an Handel, Unternehmen und Promotion und ist auf Veredelung per Stick oder Druck ausgelegt – ideal für ein gepflegtes, einheitliches Team-Outfit.", "f": ["Firmenbekleidung", "Gastronomie", "Handel"], "x": {"sitz": "Großbritannien"}},
  "Atlantis": {"t": "Atlantis Headwear ist ein italienischer Spezialist für Caps, Mützen und Hüte. Hinter der Marke steht die Master Italia S.p.A. mit Sitz in San Donà di Piave (Venetien), die als Benefit-Gesellschaft (Società Benefit) organisiert ist und unter anderem eine EcoVadis-Silbermedaille trägt.\n\nIm Programm sind klassische Baseballcaps, Trucker- und Snapback-Caps, Beanies und Fischerhüte – viele Modelle aus Bio-Baumwolle oder recycelten Materialien (GOTS, GRS, OEKO-TEX). Die Caps sind für Stick optimiert und in großer Farbauswahl erhältlich.", "f": ["Caps mit Stick", "Vereine", "Promotion"], "x": {"sitz": "San Donà di Piave, Italien", "gehoert": "Master Italia S.p.A."}},
  "AWDis": {"t": "AWDis ist ein britischer Teamwear-Anbieter, bekannt für Kollektionen mit enorm großer Farbauswahl. Zur Familie gehören Just Hoods, Just Ts, Just Polos und Just Cool sowie die nachhaltige Linie Ecologie und So Denim.\n\nAlles ist auf Veredelung ausgelegt: Abreißetiketten erleichtern das Umlabeln, produziert wird in WRAP-zertifizierten Fabriken. AWDis ist der Klassiker für Abschluss-Hoodies, Vereins- und Schulkollektionen.", "f": ["Abschlussjahrgänge", "Vereine", "Schulen"], "x": {"sitz": "Großbritannien"}},
  "B&C BE INSPIRED": {"t": "B&C gehört zu den bekanntesten Textilmarken Europas für Druck und Stick. Hinter der Marke steht die belgische The Cotton Group SA, die als B Corporation zertifiziert ist. Gefertigt wird überwiegend in Bangladesch, China und Pakistan.\n\n„B&C BE INSPIRED“ umfasst die Basics: robuste T-Shirts, Sweatshirts, Hoodies und Polos mit verlässlicher Passform, großer Farbpalette und gutem Preis-Leistungs-Verhältnis. Ein Klassiker für Teams, Vereine und Unternehmen.", "f": ["Teamwear", "Firmenbekleidung", "Vereine"], "x": {"sitz": "Belgien", "gehoert": "The Cotton Group SA"}},
  "B&C COLLECTION": {"t": "Die B&C COLLECTION ist die funktionale Linie der belgischen Marke B&C (The Cotton Group SA, B Corp). Sie ergänzt die Basics um Jacken, Fleece, Softshell, Westen und Outdoor-Bekleidung.\n\nDie Teile sind auf Wetterschutz und Alltagstauglichkeit ausgelegt und bieten gut nutzbare Flächen für Stick oder Transferdruck – ideal für Arbeitsjacken, Außendienst und Vereinsjacken.", "f": ["Arbeitsjacken", "Außendienst", "Vereine"], "x": {"sitz": "Belgien", "gehoert": "The Cotton Group SA"}},
  "Babybugz": {"t": "Babybugz ist die Babylinie von Mantis World, nach eigener Aussage das größte Babywear-Sortiment Europas. Dazu gehören Bodys, Lätzchen, Shirts, Hoodies, Jogginghosen und Mützen – vieles aus Bio-Baumwolle.\n\nMantis World wurde im Jahr 2000 von Prama Bhardwaj gegründet und gilt als Pionier für nachhaltige Textilien zum Bedrucken. Babybugz eignet sich perfekt für Geburtsgeschenke, Kitas und Familienunternehmen.", "f": ["Babygeschenke", "Kitas", "Familienfeste"], "x": {"gehoert": "Mantis World", "gegruendet": "2000 (Mantis World)"}},
  "BagBase": {"t": "BagBase ist die Taschenmarke von Beechfield Brands – Rucksäcke, Sport-, Reise- und Umhängetaschen, Turnbeutel und Kulturtaschen. Die Modelle sind funktional durchdacht und haben Flächen, auf denen Logos gut zur Geltung kommen.\n\nBeechfield Brands wurde 1995 gegründet und vereint vier Marken: Beechfield, BagBase, Quadra und Westford Mill. Das Unternehmen ist Mitglied bei „1% for the Planet“ und spendet ein Prozent des Jahresumsatzes für Umweltprojekte.", "f": ["Mitarbeitergeschenke", "Sportvereine", "Messen"], "x": {"gegruendet": "1995 (Beechfield Brands)", "sitz": "Großbritannien", "gehoert": "Beechfield Brands"}},
  "Bags2GO": {"t": "Bags2GO bietet Taschen für unterwegs – vom Baumwollbeutel über Kühltaschen bis zu Rucksäcken und Strandtaschen. Die Modelle sind praktisch, preiswert und eignen sich besonders für größere Auflagen.\n\nMit Druck werden sie zu Werbeträgern, die täglich genutzt werden: auf Messen, im Einzelhandel, als Event-Beutel oder Teilnehmer-Tasche.", "f": ["Messen", "Werbeaktionen", "Einzelhandel"], "x": {}},
  "Beechfield": {"t": "Beechfield „Original Headwear“ gehört zu den führenden Headwear-Marken Europas. Das Sortiment reicht von Baseballcaps und Trucker-Caps über Beanies, Stirnbänder und Schals bis zu Hüten – viele Modelle auch aus recycelten Materialien.\n\nHinter der Marke steht Beechfield Brands, gegründet 1995, zu der auch BagBase, Quadra und Westford Mill gehören. Die Mützen und Caps lassen sich hervorragend besticken oder mit Aufnäher veredeln.", "f": ["Wintermützen", "Caps mit Stick", "Vereine"], "x": {"gegruendet": "1995 (Beechfield Brands)", "sitz": "Großbritannien", "gehoert": "Beechfield Brands"}},
  "Bella + Canvas": {"t": "Bella + Canvas wurde 1992 in Los Angeles gegründet und steht für weiche, figurbetonte Fashion-Basics. Besonders bekannt sind die leichten Unisex-T-Shirts aus gekämmter Ringgarn-Baumwolle und Mischgeweben.\n\nDie Marke ist bei Merchandise, Modelabels und Lifestyle-Marken sehr beliebt – überall dort, wo Tragegefühl und moderner Schnitt genauso wichtig sind wie das Motiv.", "f": ["Bandmerch", "Lifestyle-Marken", "Start-ups"], "x": {"gegruendet": "1992", "sitz": "Los Angeles, USA"}},
  "Brain Waves": {"t": "Brain Waves ergänzt das Sortiment um ausgewählte Textilien für Freizeit und Alltag. Die Marke steht für unkomplizierte Produkte, die sich gut veredeln lassen.\n\nGern stellen wir Ihnen die aktuellen Modelle zusammen und beraten Sie zur passenden Veredelung – ob Druck, Stick oder Transfer.", "f": ["Promotion", "Freizeit", "Events"], "x": {}},
  "Brook Taverner": {"t": "Brook Taverner wurde 1912 in London von Frank Brook und Walter Taverner als Tuchhändler und Herrenschneiderei gegründet. Heute sitzt das Unternehmen in Keighley (West Yorkshire), beschäftigt rund 250 Mitarbeiter und verkauft ausschließlich eigene Kollektionen.\n\nNeben eigenen Herrenmode-Läden ist Corporate Clothing ein großes Standbein: Anzüge, Sakkos, Hosen, Hemden und Blusen mit Schneider-Anspruch – ideal für einen einheitlichen, professionellen Auftritt am Empfang, im Autohaus oder im Hotel.", "f": ["Empfang & Hotel", "Autohaus", "Banken"], "x": {"gegruendet": "1912", "sitz": "Keighley, Großbritannien", "mitarbeiter": "ca. 250"}},
  "Build Your Brand": {"t": "Build Your Brand ist das Streetwear-Label für eigene Kollektionen: Oversize-Shirts, Heavy Hoodies, Cargo- und Sweatpants, Kleider und Accessoires im aktuellen Urban-Look. Viele Teile gibt es in angesagten Washed- und Pastellfarben.\n\nHinter der Marke steht die TB International GmbH aus Ober-Ramstadt (Hessen), die mit 100 bis 500 Mitarbeitern mehr als 15 Mode- und Accessoire-Marken entwickelt und vertreibt – darunter Urban Classics und Mister Tee. Perfekt für Merch, Modelabels und junge Teams.", "f": ["Eigene Modelabels", "Merch", "Jugendteams"], "x": {"sitz": "Ober-Ramstadt, Deutschland", "mitarbeiter": "100–500 (TB International)", "gehoert": "TB International GmbH"}},
  "Build Your Brand Basic": {"t": "Build Your Brand Basic bietet die Streetwear-Schnitte von Build Your Brand als preisbewusste Grundausstattung – T-Shirts, Hoodies und Sweats mit modernem Look zu einem günstigeren Preis.\n\nWie Build Your Brand gehört die Linie zur TB International GmbH aus Ober-Ramstadt. Ideal für größere Stückzahlen, Events und Jugendgruppen, bei denen der Style trotzdem stimmen soll.", "f": ["Merch", "Events", "Jugendgruppen"], "x": {"sitz": "Ober-Ramstadt, Deutschland", "gehoert": "TB International GmbH"}},
  "Burnside": {"t": "Burnside ist bekannt für Flanellhemden, Hemdjacken und Workwear im amerikanischen Stil – robuste Stoffe mit Karomustern und Charakter.\n\nDie Teile passen zu Teams, die lässig und handfest auftreten wollen: im Handwerk, in der Gastronomie, im Barbershop oder in der Kreativbranche. Ein dezenter Stick auf Brust oder Ärmel macht daraus ein unverwechselbares Teamhemd.", "f": ["Handwerk", "Gastronomie", "Barber"], "x": {}},
  "Callaway": {"t": "Callaway wurde 1982 von Ely Callaway in Carlsbad (Kalifornien) gegründet und ist eine der großen Golfmarken der Welt. Neben Schlägern und Bällen bietet Callaway Golfbekleidung.\n\nIm Sortiment sind funktionale Polos, Pullover und Jacken in sportlich-eleganter Optik – ideal für Golfclubs, Turniere, Pro-Shops und Business-Events, bei denen ein hochwertiger Markenauftritt zählt.", "f": ["Golfclubs", "Turniere", "Business-Events"], "x": {"gegruendet": "1982", "sitz": "Carlsbad, USA"}},
  "CG Workwear": {"t": "CG Workwear liefert Berufsbekleidung für Gastronomie, Hotel und Service – von Kochjacken und Kochhosen über Schürzen und Kasacks bis zu Hemden und Blusen.\n\nDie Kollektionen sind auf den Alltag in Küche und Service ausgelegt: strapazierfähig, pflegeleicht und auf häufiges Waschen vorbereitet. Mit Stick erhält Ihr Team einen einheitlichen, professionellen Auftritt.", "f": ["Küche", "Service", "Hotel"], "x": {}},
  "CONA Sports": {"t": "CONA Sports ist auf Teamsport spezialisiert: Trikots, Trainingsanzüge, Shorts, Funktionsshirts und Freizeitbekleidung für den Verein.\n\nDie Teile sind atmungsaktiv, strapazierfähig und eignen sich ideal für Rückennummern, Namen und Sponsorenlogos – für Fußball, Handball, Laufgruppen und Schulsport.", "f": ["Fußball", "Handball", "Laufgruppen"], "x": {}},
  "Craghoppers": {"t": "Craghoppers wurde 1965 von Brian Gaskin und Roy Holmes in Batley (Yorkshire) gegründet. Die Gründer entwarfen die Wetterbekleidung für die Everest-Expedition von Chris Bonington 1975; von der „Kiwi“-Wanderhose wurden über zehn Millionen Paar verkauft. Seit 1995 gehört Craghoppers zur Regatta Group in Manchester.\n\nDie Expert-Linie ist speziell für Firmen und Teams mit Veredelung gedacht: Funktionsjacken, Fleece, Softshell und Hosen in Outdoor-Qualität.", "f": ["Außendienst", "Outdoor-Teams", "Tourismus"], "x": {"gegruendet": "1965", "sitz": "Manchester, Großbritannien", "gehoert": "Regatta Group"}},
  "Daiber": {"t": "Die Gustav Daiber GmbH aus Albstadt auf der Schwäbischen Alb blickt auf über 100 Jahre Erfahrung zurück und wird heute in vierter Generation geführt. Am Hauptsitz arbeiten rund 170 Menschen.\n\nDaiber versteht sich als eine der führenden Corporate-Fashion-Plattformen Europas: über 700 Artikel in bis zu 160 Farbvarianten und mehr als 15 Millionen Teile auf Lager – mit Marken wie James & Nicholson und myrtle beach sowie eigener Veredelung (Stick, Transferdruck).", "f": ["Mitarbeiter-Ausstattung", "Corporate Fashion", "Vereine"], "x": {"gegruendet": "vor über 100 Jahren", "sitz": "Albstadt, Deutschland", "mitarbeiter": "ca. 170 am Hauptsitz"}},
  "Dreamroots": {"t": "Dreamroots steht für Textilien mit Wohlfühlfaktor und natürlichem Look. Die Produkte sind für Freizeit und Zuhause gedacht und lassen sich gut mit Logo oder Schriftzug veredeln.\n\nWir stellen Ihnen das aktuelle Sortiment gern zusammen – inklusive Beratung zu Druck oder Stick.", "f": ["Geschenke", "Lifestyle", "Events"], "x": {}},
  "Ecologie": {"t": "Ecologie ist die nachhaltige Linie von AWDis: T-Shirts, Hoodies, Sweats und Jacken aus Bio-Baumwolle und recycelten Fasern, produziert nach anerkannten Umwelt- und Sozialstandards.\n\nWie alle AWDis-Marken ist Ecologie auf Veredelung ausgelegt – ideal für Teams, Vereine, NGOs und Marken, denen Umweltverantwortung wichtig ist.", "f": ["Nachhaltige Teamwear", "NGOs", "Bio-Betriebe"], "x": {"sitz": "Großbritannien", "gehoert": "AWDis"}},
  "Eecoff": {"t": "EeCoff ist ein Label für nachhaltige Unternehmensbekleidung des niederländischen Unternehmens FashionPower, das 2023 eingeführt wurde. Die Kollektion ist als vollständig zirkulär konzipiert – „Kreislaufwirtschaft beginnt am Zeichenbrett“.\n\nBesonderheit sind Stoffe mit Garnen aus Polyester und Kaffeesatz: atmungsaktiv, geruchshemmend, UV-schützend und mit „Dry-Cool“-Funktion. Im Programm sind T-Shirts, Polos, Bodywarmer, Pullover und Softshelljacken.", "f": ["Nachhaltige Firmenbekleidung", "Außendienst", "Service"], "x": {"gegruendet": "2023 (Label)", "sitz": "Niederlande", "gehoert": "FashionPower"}},
  "EXCD by Promodoro": {"t": "EXCD ist die Premium-Linie der deutschen Marke Promodoro: schwere Stoffe, saubere Verarbeitung und moderne Schnitte für Shirts, Sweats und Jacken, die sich hochwertig anfühlen und lange halten.\n\nPromodoro wurde 1989 von Martin Keller gegründet und hat seitdem nach eigenen Angaben über 90 Millionen Textilien verkauft – anfangs vor allem für Band-Merchandise und Festivals.", "f": ["Premium-Merch", "Firmenbekleidung", "Mode"], "x": {"gegruendet": "1989 (Promodoro)", "sitz": "Deutschland", "gehoert": "Promodoro"}},
  "Exner": {"t": "Exner – „Mode mit System“ – bietet Berufs- und Imagebekleidung, die sich im Team kombinieren lässt: Kochjacken, Kasacks, Tuniken, Mäntel, Blusen und Schürzen.\n\nHinter der Marke steht die Exner Fashion GmbH aus Oer-Erkenschwick (NRW). Die Kollektionen eignen sich für Gastronomie, Pflege, Praxis und Service – überall, wo ein einheitlicher, gepflegter Look über viele Bereiche gefragt ist.", "f": ["Gastronomie", "Pflege", "Service"], "x": {"sitz": "Oer-Erkenschwick, Deutschland", "gehoert": "Exner Fashion GmbH"}},
  "Fair Towel": {"t": "Fair Towel steht für fair produzierte Handtücher, Bademäntel und Frottierwaren – mit Fokus auf transparente Lieferketten und nachhaltige Baumwolle.\n\nMit eingesticktem Logo oder Namen sind die Tücher ein nachhaltiges Geschenk für Kunden und Mitarbeiter und passen perfekt in Hotels, Spas und Fitnessstudios.", "f": ["Hotels", "Spa & Wellness", "Kundengeschenke"], "x": {}},
  "Fare": {"t": "FARE wurde am 3. Januar 1955 von Guenther Fassbender und seiner Frau Margot gegründet und sitzt in Remscheid. 1989 brachte FARE nach eigenen Angaben den weltweit ersten automatisch öffnenden und schließenden Taschenschirm auf den Markt. 2023 beschäftigte das Unternehmen rund 60 Mitarbeiter; seit 2007 ist es Schwesterfirma von Halfar und mbw.\n\nIm Sortiment sind Stockschirme, Taschenschirme, Golf- und Gästeschirme – mit Ihrem Logo bedruckt ein Werbeträger, der wirklich genutzt wird.", "f": ["Werbeschirme", "Golf", "Hotels"], "x": {"gegruendet": "1955", "sitz": "Remscheid, Deutschland", "mitarbeiter": "ca. 60 (2023)"}},
  "Finden & Hales": {"t": "Finden & Hales ist die Sportmarke aus der Henbury-Gruppe: Funktionsshirts, Polos, Jacken und Trainingskleidung mit sportlichen Details wie Kontrastpaspeln.\n\nHenbury Ltd wurde 1997 gegründet und vereint neun Marken – darunter Henbury, SF, Tombo, Towel City, Mumbles und Larkwood. Finden & Hales passt zu Laufgruppen, Sportevents und Vereinen.", "f": ["Laufevents", "Vereine", "Fitness"], "x": {"gegruendet": "1997 (Henbury)", "sitz": "Großbritannien", "gehoert": "Henbury Ltd"}},
  "Flexfit": {"t": "Flexfit ist die bekannteste Marke von Yupoong, einem Cap-Hersteller, der 1974 gegründet wurde und 2024 sein 50-jähriges Bestehen feierte. Flexfit-Caps sind seit rund 30 Jahren für ihr Stretchband bekannt, das ohne Verschluss perfekt sitzt.\n\nDazu kommen Snapbacks, Trucker- und Dad-Caps. In Europa werden die Caps unter anderem über TB International vertrieben. Erste Wahl für hochwertige Caps mit 3D-Stick.", "f": ["Caps mit 3D-Stick", "Merch", "Teams"], "x": {"gegruendet": "1974 (Yupoong)", "gehoert": "Yupoong Inc."}},
  "Fruit of the Loom": {"t": "Fruit of the Loom wurde 1851 in den USA gegründet und hat seinen Sitz in Bowling Green (Kentucky). Seit 2002 gehört das Unternehmen zur Holding Berkshire Hathaway von Warren Buffett.\n\nDie Marke ist seit Jahrzehnten eine feste Größe für Basics: T-Shirts, Sweatshirts, Hoodies und Polos zum fairen Preis in vielen Farben – ideal für größere Auflagen, Events und Vereine.", "f": ["Events", "Vereine", "Promotion"], "x": {"gegruendet": "1851", "sitz": "Bowling Green, USA", "gehoert": "Berkshire Hathaway"}},
  "Gildan": {"t": "Gildan wurde 1984 in Montréal (Kanada) gegründet und gehört zu den größten Herstellern von Basic-Textilien weltweit. Das Unternehmen produziert zu großen Teilen in eigenen Werken.\n\nIm Sortiment sind preiswerte T-Shirts, Hoodies und Sweats in verlässlicher Qualität – perfekt für hohe Stückzahlen, Festivals, Events und Schulaktionen.", "f": ["Großauflagen", "Events", "Festivals"], "x": {"gegruendet": "1984", "sitz": "Montréal, Kanada"}},
  "Halfar": {"t": "Halfar wurde 1986 von Armin Halfar gegründet – einem Rettungssanitäter, der leichtere und bessere Rettungstaschen bauen wollte. Heute sitzt die Halfar System GmbH in Bielefeld und ist Spezialist für Taschen und Rucksäcke mit Werbeanbringung. Seit 2007 gehören die Schwesterfirmen FARE und mbw zur Gruppe.\n\nHalfar ist EcoVadis-Gold-zertifiziert (2022), betreibt seit 2019 ein eigenes Logistikzentrum und entwickelt auch individuelle Taschen-Kollektionen.", "f": ["Business-Taschen", "Mitarbeitergeschenke", "Messen"], "x": {"gegruendet": "1986", "sitz": "Bielefeld, Deutschland"}},
  "Halink": {"t": "Halink bietet Berufs- und Freizeittextilien mit den Linien Link Kids Wear und Link Kitchen Wear – praktische Produkte für Küche, Kita und Alltag.\n\nDie Teile sind robust, pflegeleicht und gut zu besticken oder zu bedrucken – ideal für Gastronomie, Kochschulen, Kitas und Vereinsfeste.", "f": ["Gastronomie", "Kitas", "Freizeit"], "x": {}},
  "Link Kids Wear": {"t": "Link Kids Wear ist die Kinderlinie von Halink – Shirts, Schürzen, Malkittel und Accessoires in kindgerechten Größen und Farben.\n\nDie Textilien sind robust und waschbar und eignen sich ideal für Kitas, Schulen, Kinderfeste und Vereine mit Nachwuchsabteilung.", "f": ["Kitas", "Schulen", "Kinderfeste"], "x": {"gehoert": "Halink"}},
  "Link Kitchen Wear": {"t": "Link Kitchen Wear (Halink) liefert Schürzen, Kochjacken und Küchentextilien für Profis und Hobbyköche.\n\nMit Logo bestickt sind die Teile ideal für Restaurants, Kochschulen, Catering, Grill-Events und als Geschenk für Kunden.", "f": ["Restaurants", "Kochschulen", "Catering"], "x": {"gehoert": "Halink"}},
  "Henbury": {"t": "Henbury wurde 1997 in Großbritannien gegründet und steht für Firmenbekleidung mit Stil: Hemden, Polos, Strick, Westen und Accessoires in klassischen Schnitten.\n\nZur Henbury-Gruppe gehören neun Marken für Corporate, Promotion und Workwear – darunter SF, Finden & Hales, Tombo, Towel City, Mumbles, Larkwood und Splashmacs. Henbury ist ideal für Teams mit Kundenkontakt.", "f": ["Firmenbekleidung", "Gastronomie", "Hotel"], "x": {"gegruendet": "1997", "sitz": "Großbritannien"}},
  "HRM": {"t": "HRM ist die Marke der HRM Textil GmbH aus Stuttgart – „styled to impress, made to last“. Die Kollektion umfasst Polos, T-Shirts, Hoodies, Sweatjacken, Hemden und Blusen.\n\nViele Teile sind GOTS- und OEKO-TEX-zertifiziert; die Polos aus Ringgarn-Piqué sind bis 60 °C waschbar und haben verstärkte Kragen. HRM präsentierte sich 2018 erstmals einem breiten Fachpublikum auf der TV TecStyle Visions.", "f": ["Firmenbekleidung", "Handel", "Service"], "x": {"sitz": "Stuttgart, Deutschland", "gehoert": "HRM Textil GmbH"}},
  "Jerzees": {"t": "Jerzees ist eine traditionsreiche US-Marke für Sweatshirts, Hoodies und T-Shirts. In Europa wurde sie über Russell Europe bekannt und gehört wie Russell zur Fruit-of-the-Loom-Gruppe.\n\nDie Marke steht für bewährte Basics mit gutem Preis-Leistungs-Verhältnis – ideal für Teams, Schulen und Events.", "f": ["Teams", "Schulen", "Events"], "x": {"gehoert": "Fruit of the Loom"}},
  "JHK": {"t": "JHK ist ein spanischer Spezialist für Werbetextilien mit Zentrale in Fuenlabrada (Madrid) und Zentrallager in Noblejas (Toledo). Zur JHK Trader Group gehören Gesellschaften in Spanien, Frankreich und den USA.\n\nDas Sortiment reicht von T-Shirts und Polos in vielen Grammaturen über Sublimations-, Workwear- und Sportlinien bis zu Unterwäsche. JHK ist ISO 9001 und 14001 zertifiziert. 2025 übernahm der Investor GPF Partners eine Mehrheit und unterstützt den Zusammenschluss mit Gor Factory (Roly).", "f": ["Promotion", "Vereine", "Mitarbeiter"], "x": {"sitz": "Fuenlabrada, Spanien"}},
  "Just Cool": {"t": "Just Cool ist die Funktionslinie von AWDis: atmungsaktive Sportshirts, Tanks, Laufjacken und Trainingsbekleidung – leicht und schnell trocknend.\n\nWie alle AWDis-Marken ist die Linie für Veredelung gemacht: Abreißetiketten erleichtern das Umlabeln, gefertigt wird in WRAP-zertifizierten Fabriken.", "f": ["Laufevents", "Fitness", "Vereine"], "x": {"sitz": "Großbritannien", "gehoert": "AWDis"}},
  "Just Hoods": {"t": "Just Hoods startete 2008 mit einem einzigen Modell, dem College Hoodie JH001, und ist die erste Marke der AWDis-Familie. Heute ist sie der Hoodie-Spezialist schlechthin – mit vielen Dutzend Modellen in über 100 Farben, College-Hoodies, Zip-Jacken und Heavyweight-Varianten mit 330 g/m².\n\nWie alle AWDis-Marken ist die Linie für Veredelung gemacht: Abreißetiketten erleichtern das Umlabeln, gefertigt wird in WRAP-zertifizierten Fabriken.", "f": ["Abschluss-Hoodies", "Vereine", "Schulen"], "x": {"sitz": "Großbritannien", "gehoert": "AWDis"}},
  "Just Polos": {"t": "Just Polos von AWDis bietet Poloshirts in vielen Farben und Schnitten – vom Basic-Polo bis zum Sportpolo mit Funktionsmaterial.\n\nWie alle AWDis-Marken ist die Linie für Veredelung gemacht: Abreißetiketten erleichtern das Umlabeln, gefertigt wird in WRAP-zertifizierten Fabriken.", "f": ["Firmen", "Vereine", "Events"], "x": {"sitz": "Großbritannien", "gehoert": "AWDis"}},
  "Just Ts": {"t": "Just Ts von AWDis liefert T-Shirts in großer Farbauswahl und modernen Schnitten – die preiswerte Basis für Drucke in jeder Auflage.\n\nWie alle AWDis-Marken ist die Linie für Veredelung gemacht: Abreißetiketten erleichtern das Umlabeln, gefertigt wird in WRAP-zertifizierten Fabriken.", "f": ["Events", "Schulen", "Vereine"], "x": {"sitz": "Großbritannien", "gehoert": "AWDis"}},
  "Karlowsky": {"t": "Karlowsky ist die Marke der Karlowsky Fashion GmbH aus Wanzleben-Börde bei Magdeburg (Sachsen-Anhalt), im Handelsregister seit 2008. Das Unternehmen entwickelt Berufsbekleidung vor allem für Gastronomie, Fleischerhandwerk, Küche und Klinik.\n\nIm Programm sind Kochjacken, Schürzen, Hosen, Kasacks, Polos, Shirts, Handschuhe und Schuhe – modern geschnitten und pflegeleicht. Daneben fertigt Karlowsky auch Merchandise, etwa für den 1. FC Magdeburg.", "f": ["Küche", "Service", "Handwerk"], "x": {"gegruendet": "2008", "sitz": "Wanzleben-Börde, Deutschland", "gehoert": "Karlowsky Fashion GmbH"}},
  "Korntex": {"t": "Korntex wurde 2007 gegründet, sitzt in Fellbach bei Stuttgart und hat sich auf Warnschutz spezialisiert: Warnwesten und -jacken, Arbeitsbekleidung und persönliche Schutzausrüstung. Produziert wird überwiegend im eigenen Werk in China.\n\nDie Westen erfüllen Normen wie EN ISO 20471 und EN 17353; die Produktion ist nach ISO 9001 zertifiziert. Erklärtes Ziel: Europas führender Anbieter für Warnschutzkleidung zu werden. Mit Logo bedruckt ideal für Bau, Logistik, Events und Vereine.", "f": ["Bau & Logistik", "Events", "Vereine"], "x": {"gegruendet": "2007", "sitz": "Fellbach, Deutschland"}},
  "Kustom Kit": {"t": "Kustom Kit ist eine britische Marke für Firmen- und Freizeitbekleidung in vielen Passformen: Hemden, Blusen, Polos wie das bekannte „Klassic Polo“ und Strick.\n\nKustom Kit gehört zur Charterhouse Holdings mit Sitz in Castle Donington (Großbritannien), zu der auch Xpres und Vanilla gehören. Die Kollektion ist klassisch, solide und gut für einen professionellen Auftritt.", "f": ["Firmenbekleidung", "Gastronomie", "Handel"], "x": {"sitz": "Castle Donington, Großbritannien", "gehoert": "Charterhouse Holdings"}},
  "Larkwood": {"t": "Larkwood ist auf Baby- und Kleinkindbekleidung spezialisiert – Bodys, Shirts, Hoodies, Sweats und Lätzchen in weicher Baumwolle.\n\nDie Marke gehört zur Henbury-Gruppe (gegründet 1997). Larkwood eignet sich für Geburtsgeschenke, Kitas und Familienunternehmen.", "f": ["Babygeschenke", "Kitas", "Familienbetriebe"], "x": {"sitz": "Großbritannien", "gehoert": "Henbury Ltd"}},
  "Mantis": {"t": "Mantis World wurde im Jahr 2000 von Prama Bhardwaj gegründet und gilt als Pionier für nachhaltige Textilien zum Bedrucken. Die Marke setzt konsequent auf Bio-Baumwolle, ist als B Corporation zertifiziert und zeigt auf jeder Produktseite die Einsparungen an Wasser, Energie und CO₂.\n\nIm Programm sind moderne T-Shirts, Sweats, Hoodies und Taschen sowie die Kinderlinien Mantis Mini und Mantis Kids und die Babylinie Babybugz.", "f": ["Nachhaltige Marken", "Teams", "Merch"], "x": {"gegruendet": "2000", "sitz": "Großbritannien"}},
  "Marvelis": {"t": "Marvelis ist ein Hemdenspezialist mit hochwertigen Business-Hemden in verschiedenen Passformen – von Body Fit bis Comfort Fit – sowie Freizeithemden.\n\nDie Hemden sind bügelleicht und für den täglichen Einsatz gemacht. Mit dezentem Stick sind sie ideal für Bank, Autohaus, Empfang und Verkauf.", "f": ["Banken", "Autohaus", "Empfang"], "x": {}},
  "mbw": {"t": "mbw sitzt in Wanderup (Schleswig-Holstein) und ist bekannt für Werbeartikel mit Persönlichkeit – vor allem Plüschtiere und kreative Give-aways. Seit 2007 ist mbw Schwesterfirma von Halfar und FARE.\n\nMit Ihrem Logo auf T-Shirt, Schal oder Mütze werden die Plüschtiere zu sympathischen Markenbotschaftern auf Messen und bei Kinder-Events.", "f": ["Give-aways", "Messen", "Kinder"], "x": {"sitz": "Wanderup, Deutschland"}},
  "Miners Mate": {"t": "Miners Mate bietet praktische Begleiter für Freizeit und Alltag, mit eigenen Linien wie „mymate“, „mypuremate“ und „mysupersizemate“.\n\nGern stellen wir Ihnen die passenden Modelle für Ihre Aktion zusammen – inklusive Beratung zur Veredelung.", "f": ["Promotion", "Freizeit", "Events"], "x": {}},
  "Mr. Socks": {"t": "Mr. Socks ist auf Socken spezialisiert – vom Sportsocken-Klassiker bis zum modischen Design.\n\nMit eingestricktem Logo oder in Vereinsfarben sind Socken ein origineller Werbeartikel und ein beliebter Teil des Teamoutfits.", "f": ["Vereine", "Merch", "Give-aways"], "x": {}},
  "Mumbles": {"t": "Mumbles ist die Marke für Accessoires und Headwear für Groß und Klein – Mützen, Schals, Handschuhe, Teddys und mehr.\n\nMumbles gehört zur Henbury-Gruppe (gegründet 1997) und ist ideal für Winteraktionen, Kinder-Events und Fanartikel.", "f": ["Winteraktionen", "Kinder", "Events"], "x": {"sitz": "Großbritannien", "gehoert": "Henbury Ltd"}},
  "Neo Blu": {"t": "Neo Blu ist die Denim-Linie der französischen Marke SOL'S: Jeans, Jeansjacken, Hemden und Shirts mit modischem Schnitt.\n\nSOL'S wurde 1991 gegründet und erzielte 2019 rund 138,5 Millionen Euro Umsatz. Neo Blu passt zu Teams, die ihren Look lässig und hochwertig zugleich wollen.", "f": ["Gastronomie", "Handel", "Kreativbranche"], "x": {"sitz": "Frankreich", "gehoert": "SOL'S"}},
  "Neutral": {"t": "Neutral sitzt in Kopenhagen und steht für zertifiziert nachhaltige Textilien aus Bio-Baumwolle. Hinter der Marke stehen mehr als 20 Jahre Erfahrung aus der Textilindustrie; seit 2008 tritt sie als eigene Plattform auf. Produziert wird ausschließlich in Indien.\n\nNeutral trägt Siegel wie Fairtrade, EU Ecolabel, GOTS und SA8000 und ist als B Corporation zertifiziert. Ideal für Unternehmen und öffentliche Auftraggeber, bei denen Nachhaltigkeit belegbar sein muss.", "f": ["Zertifizierte Nachhaltigkeit", "Öffentliche Auftraggeber", "NGOs"], "x": {"gegruendet": "2008", "sitz": "Kopenhagen, Dänemark"}},
  "New Morning Studios": {"t": "New Morning Studios ist eine moderne Basic-Marke mit Designanspruch und gehört wie Build Your Brand zum Portfolio der TB International GmbH aus Ober-Ramstadt.\n\nDie Teile verbinden zeitgemäße Schnitte mit nachhaltigen Materialien – gut geeignet für Merch, Lifestyle-Marken und Teams.", "f": ["Merch", "Lifestyle", "Teams"], "x": {"sitz": "Ober-Ramstadt, Deutschland", "gehoert": "TB International GmbH"}},
  "Next Level Apparel": {"t": "Next Level Apparel wurde 2003 in den USA gegründet und wurde als Pionier für Blanko-Textilien im Printwear-Markt bekannt – unter anderem durch ein T-Shirt speziell für Sublimationsdruck.\n\nSeit November 2023 gehört auch die Marke Stedman zu Next Level. Die weichen, modischen T-Shirts und Basics sind beliebt für Merchandise mit hochwertigem Tragegefühl.", "f": ["Merch", "Bands", "Lifestyle-Marken"], "x": {"gegruendet": "2003", "sitz": "USA"}},
  "Onna by Premier": {"t": "Onna by Premier bietet moderne Berufsbekleidung für Pflege, Beauty und Wellness – Kasacks, Tuniken, Hosen und Jacken mit durchdachten Details und Stretch-Komfort.\n\nDie Linie gehört zur britischen Workwear-Marke Premier. Die Teile sind bequem, funktional und gut zu besticken.", "f": ["Pflege", "Kosmetik", "Spa"], "x": {"sitz": "Großbritannien", "gehoert": "Premier"}},
  "Portman & Pooch": {"t": "Portman & Pooch ergänzt das Sortiment um ausgewählte Accessoires mit Charme.\n\nGern zeigen wir Ihnen die aktuellen Modelle auf Anfrage und beraten Sie zur Veredelung.", "f": ["Geschenke", "Accessoires", "Events"], "x": {}},
  "Premier": {"t": "Premier Workwear ist eine britische Marke für Berufsbekleidung: Hemden, Blusen, Schürzen, Kasacks, Kochjacken, Westen und Arbeitsjacken für Gastronomie, Handel, Pflege und Service.\n\nZur Marke gehört auch die Linie Onna by Premier für Pflege und Beauty. Die Kollektionen sind praktisch, pflegeleicht und für viele Branchen gedacht.", "f": ["Gastronomie", "Pflege", "Einzelhandel"], "x": {"sitz": "Großbritannien"}},
  "Promodoro": {"t": "Promodoro wurde 1989 von Martin Keller gegründet – die Idee für zeitlose Blanko-Basics entstand auf einer Südamerika-Reise, der Name beim Wein in einem Düsseldorfer Restaurant (inspiriert vom italienischen „pomodoro“). Angefangen hat alles in einer Garage.\n\nSeitdem hat Promodoro nach eigenen Angaben über 90 Millionen Textilien verkauft. Neben den Basics gibt es die Premiumlinie EXCD und die Modelinie X.O.", "f": ["Firmen", "Vereine", "Merch"], "x": {"gegruendet": "1989", "sitz": "Deutschland"}},
  "Quadra": {"t": "Quadra ist die Taschenmarke von Beechfield Brands für Business, Sport und Reisen: Rucksäcke, Laptoptaschen, Sporttaschen und Trolleys.\n\nBeechfield Brands wurde 1995 gegründet und ist Mitglied bei „1% for the Planet“. Die Quadra-Taschen sind funktional durchdacht und bieten gut nutzbare Flächen für Ihr Logo.", "f": ["Business", "Sport", "Mitarbeitergeschenke"], "x": {"gegruendet": "1995 (Beechfield Brands)", "sitz": "Großbritannien", "gehoert": "Beechfield Brands"}},
  "Quikflip": {"t": "Quikflip steht für originelle Hoodies und Jacken mit cleveren Extras.\n\nEin Hingucker für Merch, Festivals und Events – gern beraten wir zu den aktuellen Modellen und zur passenden Veredelung.", "f": ["Merch", "Festivals", "Events"], "x": {}},
  "Rabbit Skins": {"t": "Rabbit Skins ist eine US-Marke für Baby- und Kinderbekleidung: Bodys, Shirts, Hoodies und Lätzchen in vielen Farben und weicher Baumwolle.\n\nIdeal für Geburtsgeschenke, Kinder-Merch und Kitas.", "f": ["Babygeschenke", "Kinder-Merch", "Kitas"], "x": {"sitz": "USA"}},
  "Reebok": {"t": "Reebok wurde 1958 in Bolton (England) gegründet und ist eine der bekanntesten Sportmarken der Welt. Unterwäsche und Socken von Reebok werden als Lizenzkollektion angeboten.\n\nDie Teile verbinden die bekannte Sportmarke mit Komfort im Alltag – beliebt als Teil eines Sportpakets für Vereine oder als Geschenk für Mitarbeiter.", "f": ["Sportvereine", "Mitarbeiter", "Geschenke"], "x": {"gegruendet": "1958"}},
  "Regatta Professional": {"t": "Regatta Professional ist die Firmenlinie der Outdoor-Marke Regatta: wetterfeste Jacken, Softshell, Fleece und Westen – robust für Außendienst und Arbeit im Freien.\n\nRegatta wurde 1981 von Lionel Black in Manchester gegründet und ist bis heute in Familienbesitz. Zur Regatta Group gehören auch Craghoppers und Dare2b; das Unternehmen erhielt 2012 und 2013 den Queen's Award for Enterprise.", "f": ["Außendienst", "Handwerk", "Outdoor-Teams"], "x": {"gegruendet": "1981", "sitz": "Manchester, Großbritannien", "gehoert": "Regatta Group"}},
  "Regatta High Visibility": {"t": "Regatta High Visibility bietet Warnschutzkleidung für Arbeit, Verkehr und Sicherheit – gut sichtbar, wetterfest und mit Platz für Ihr Logo.\n\nRegatta wurde 1981 von Lionel Black in Manchester gegründet und ist bis heute in Familienbesitz. Zur Regatta Group gehören auch Craghoppers und Dare2b; das Unternehmen erhielt 2012 und 2013 den Queen's Award for Enterprise.", "f": ["Bau", "Logistik", "Sicherheit"], "x": {"gegruendet": "1981", "sitz": "Manchester, Großbritannien", "gehoert": "Regatta Group"}},
  "Regatta Honestly Made": {"t": "Regatta Honestly Made ist die nachhaltige Linie mit recycelten Materialien – Fleece, Jacken und Softshell mit gutem Gewissen.\n\nRegatta wurde 1981 von Lionel Black in Manchester gegründet und ist bis heute in Familienbesitz. Zur Regatta Group gehören auch Craghoppers und Dare2b; das Unternehmen erhielt 2012 und 2013 den Queen's Award for Enterprise.", "f": ["Nachhaltige Teams", "Außendienst", "Outdoor"], "x": {"gegruendet": "1981", "sitz": "Manchester, Großbritannien", "gehoert": "Regatta Group"}},
  "Replay": {"t": "Replay ist eine italienische Modemarke, bekannt vor allem für Denim. Unterwäsche und Socken von Replay werden als Lizenzkollektion angeboten.\n\nDie Teile bringen italienischen Modestil in die Basics – hochwertige Geschenke für Mitarbeiter und Kunden.", "f": ["Geschenke", "Mode", "Mitarbeiter"], "x": {"sitz": "Italien"}},
  "Result": {"t": "Result Clothing sitzt in Colchester (Großbritannien) und versteht sich als Pionier für Performance-Outdoor- und Activewear. 1994 startete ein kleines Team mit zehn Lagerartikeln – heute umfasst das Sortiment über 450 Produkte in mehr als 6.000 Varianten von Kindergröße bis 4XL.\n\nZum Programm gehören Funktionsjacken, Softshell, Fleece und Headwear sowie Unterlinien für Arbeit (Work-Guard), Warnschutz (Safe-Guard), Winter, Recycling und Sport (Spiro). Lager in Großbritannien ermöglicht schnelle Lieferung.", "f": ["Außendienst", "Vereine", "Arbeit im Freien"], "x": {"sitz": "Colchester, Großbritannien", "gehoert": "Result Clothing Ltd"}},
  "Result Core": {"t": "Result Core ist die preisbewusste Grundausstattung von Result: Softshell, Fleece und Jacken mit gutem Wetterschutz für Teams und Mitarbeiter.\n\nResult Clothing sitzt in Colchester (Großbritannien) und startete 1994 mit zehn Lagerartikeln; heute umfasst das Sortiment über 450 Produkte in mehr als 6.000 Varianten.", "f": ["Mitarbeiterjacken", "Vereine", "Außendienst"], "x": {"sitz": "Colchester, Großbritannien", "gehoert": "Result Clothing Ltd"}},
  "Result Headwear": {"t": "Result Headwear liefert Caps, Mützen und Winter-Accessoires – vom Basic-Cap bis zur gefütterten Mütze. Ideal zum Besticken.\n\nResult Clothing sitzt in Colchester (Großbritannien) und startete 1994 mit zehn Lagerartikeln; heute umfasst das Sortiment über 450 Produkte in mehr als 6.000 Varianten.", "f": ["Caps", "Wintermützen", "Promotion"], "x": {"sitz": "Colchester, Großbritannien", "gehoert": "Result Clothing Ltd"}},
  "Result Recycled": {"t": "Result Recycled verarbeitet recycelte Materialien zu Jacken, Fleece und Softshell – funktional und nachhaltiger.\n\nResult Clothing sitzt in Colchester (Großbritannien) und startete 1994 mit zehn Lagerartikeln; heute umfasst das Sortiment über 450 Produkte in mehr als 6.000 Varianten.", "f": ["Nachhaltige Teams", "Außendienst", "Outdoor"], "x": {"sitz": "Colchester, Großbritannien", "gehoert": "Result Clothing Ltd"}},
  "Result Safe-Guard": {"t": "Result Safe-Guard ist die Warnschutzlinie: Westen, Jacken und Accessoires in Signalfarben für mehr Sicherheit.\n\nResult Clothing sitzt in Colchester (Großbritannien) und startete 1994 mit zehn Lagerartikeln; heute umfasst das Sortiment über 450 Produkte in mehr als 6.000 Varianten.", "f": ["Bau", "Logistik", "Events"], "x": {"sitz": "Colchester, Großbritannien", "gehoert": "Result Clothing Ltd"}},
  "Result Winter Essentials": {"t": "Result Winter Essentials bietet Mützen, Schals und Handschuhe für die kalte Jahreszeit – perfekte Winter-Werbeartikel mit Stick.\n\nResult Clothing sitzt in Colchester (Großbritannien) und startete 1994 mit zehn Lagerartikeln; heute umfasst das Sortiment über 450 Produkte in mehr als 6.000 Varianten.", "f": ["Winteraktionen", "Weihnachtsmärkte", "Vereine"], "x": {"sitz": "Colchester, Großbritannien", "gehoert": "Result Clothing Ltd"}},
  "Result Work-Guard": {"t": "Result Work-Guard ist robuste Arbeitskleidung für Handwerk und Industrie: Jacken, Westen und Hosen mit vielen Taschen und verstärkten Nähten.\n\nResult Clothing sitzt in Colchester (Großbritannien) und startete 1994 mit zehn Lagerartikeln; heute umfasst das Sortiment über 450 Produkte in mehr als 6.000 Varianten.", "f": ["Handwerk", "Industrie", "Bau"], "x": {"sitz": "Colchester, Großbritannien", "gehoert": "Result Clothing Ltd"}},
  "Spiro": {"t": "Spiro ist die Sportmarke von Result: Funktionsshirts, Trainingskleidung und Lauf-Outfits mit sportlichen Details.\n\nResult Clothing sitzt in Colchester (Großbritannien) und startete 1994 mit zehn Lagerartikeln; heute umfasst das Sortiment über 450 Produkte in mehr als 6.000 Varianten.", "f": ["Laufgruppen", "Fitness", "Vereine"], "x": {"sitz": "Colchester, Großbritannien", "gehoert": "Result Clothing Ltd"}},
  "Roly": {"t": "Roly ist die Hauptmarke von Gor Factory, einem 1985 gegründeten Textilunternehmen aus Murcia (Spanien) und einem der großen europäischen Anbieter für bedruckbare Textilien. 2025 hat der Investor GPF Partners den Zusammenschluss von Gor Factory mit JHK unterstützt, um einen europäischen Marktführer für Werbetextilien zu schaffen.\n\nDas Sortiment reicht von Basics über Sport (Roly Sport, Stamina) und Workwear (Roly WRK) bis zu Schuhen (Roly Footwear) und der nachhaltigen Linie Roly Eco.", "f": ["Vereine", "Firmen", "Sport"], "x": {"gegruendet": "1985 (Gor Factory)", "sitz": "Murcia, Spanien", "gehoert": "Gor Factory"}},
  "Roly Eco": {"t": "Roly Eco ist die nachhaltige Linie von Roly mit Bio-Baumwolle und recycelten Materialien.\n\nHinter der Linie steht Gor Factory aus Murcia (Spanien), gegründet 1985 und einer der großen europäischen Anbieter für bedruckbare Textilien.", "f": ["Nachhaltigkeit", "Teams", "Merch"], "x": {"gegruendet": "1985 (Gor Factory)", "sitz": "Murcia, Spanien", "gehoert": "Gor Factory"}},
  "Roly Footwear": {"t": "Roly Footwear ergänzt Berufsbekleidung um passende Arbeitsschuhe für Gastronomie, Pflege und Handwerk.\n\nHinter der Linie steht Gor Factory aus Murcia (Spanien), gegründet 1985 und einer der großen europäischen Anbieter für bedruckbare Textilien.", "f": ["Gastronomie", "Pflege", "Handwerk"], "x": {"gegruendet": "1985 (Gor Factory)", "sitz": "Murcia, Spanien", "gehoert": "Gor Factory"}},
  "Roly Sport": {"t": "Roly Sport liefert Trikots, Trainingsanzüge und Funktionsshirts für den Vereinssport – ideal mit Nummern und Sponsorlogos.\n\nHinter der Linie steht Gor Factory aus Murcia (Spanien), gegründet 1985 und einer der großen europäischen Anbieter für bedruckbare Textilien.", "f": ["Fußball", "Teamsport", "Schulen"], "x": {"gegruendet": "1985 (Gor Factory)", "sitz": "Murcia, Spanien", "gehoert": "Gor Factory"}},
  "Roly Workwear": {"t": "Roly Workwear (WRK) bietet strapazierfähige Arbeitskleidung für Handwerk, Industrie und Logistik.\n\nHinter der Linie steht Gor Factory aus Murcia (Spanien), gegründet 1985 und einer der großen europäischen Anbieter für bedruckbare Textilien.", "f": ["Handwerk", "Logistik", "Industrie"], "x": {"gegruendet": "1985 (Gor Factory)", "sitz": "Murcia, Spanien", "gehoert": "Gor Factory"}},
  "Stamina": {"t": "Stamina ist die Sportlinie von Gor Factory (Roly) mit Funktionsbekleidung für Training und Wettkampf.\n\nHinter der Linie steht Gor Factory aus Murcia (Spanien), gegründet 1985 und einer der großen europäischen Anbieter für bedruckbare Textilien.", "f": ["Teamsport", "Fitness", "Vereine"], "x": {"gegruendet": "1985 (Gor Factory)", "sitz": "Murcia, Spanien", "gehoert": "Gor Factory"}},
  "RTP Apparel": {"t": "RTP Apparel ist die junge Modelinie der französischen Marke SOL'S – mit Oversize-Schnitten, schweren Stoffen und Streetwear-Details.\n\nSOL'S wurde 1991 gegründet und gehört mit rund 138,5 Millionen Euro Umsatz (2019) zu den großen Marken für Textilveredelung. RTP passt zu Merch, Jugendteams und Lifestyle-Marken.", "f": ["Merch", "Jugendteams", "Lifestyle"], "x": {"sitz": "Frankreich", "gehoert": "SOL'S"}},
  "Russell": {"t": "Russell wurde 1902 von Benjamin Russell in Alexander City (Alabama, USA) gegründet und steht seitdem für Sportbekleidung. Heute gehört die Marke zur Fruit-of-the-Loom-Gruppe.\n\nIm Sortiment sind robuste Sweats, Polos, Hemden und Jacken mit langer Haltbarkeit – mit den Linien Russell Collection (Business) und Pure Organic (Bio-Baumwolle). Ein Klassiker für Firmen, Vereine und Schulen.", "f": ["Firmenbekleidung", "Vereine", "Schulen"], "x": {"gegruendet": "1902", "sitz": "USA", "gehoert": "Fruit of the Loom"}},
  "Russell Collection": {"t": "Die Russell Collection umfasst Business-Hemden, Blusen, Strick und Jacken – gepflegt, bügelleicht und alltagstauglich.\n\nRussell wurde 1902 in Alexander City (Alabama) gegründet und gehört heute zur Fruit-of-the-Loom-Gruppe.", "f": ["Büro", "Empfang", "Verkauf"], "x": {"gegruendet": "1902", "sitz": "USA", "gehoert": "Fruit of the Loom"}},
  "Russell Pure Organic": {"t": "Russell Pure Organic bietet die bewährte Russell-Qualität aus Bio-Baumwolle – T-Shirts, Polos und Sweats.\n\nRussell wurde 1902 in Alexander City (Alabama) gegründet und gehört heute zur Fruit-of-the-Loom-Gruppe.", "f": ["Nachhaltige Teams", "Firmen", "Vereine"], "x": {"gegruendet": "1902", "sitz": "USA", "gehoert": "Fruit of the Loom"}},
  "Seidensticker": {"t": "Seidensticker wurde 1919 von Walter Seidensticker sen. in Bielefeld gegründet und ist bis heute ein Familienunternehmen. Nach eigenen Angaben hat kein Hersteller in Deutschland mehr Hemden verkauft; Seidensticker zählt zu den drei größten Hemdenanbietern weltweit. Für ein Hemd sind rund 80 Arbeitsschritte und 142 Qualitätskontrollen nötig.\n\nBekannt sind die bügelleichten Business-Hemden und Blusen mit der Rose am Kragen – mit dezentem Stick ideal für Banken, Autohäuser, Hotels und alle Teams mit Kundenkontakt.", "f": ["Banken & Versicherungen", "Autohaus", "Hotel"], "x": {"gegruendet": "1919", "sitz": "Bielefeld, Deutschland"}},
  "SF Clothing": {"t": "SF Clothing (SF Men, SF Women, SF Minni) bietet modische Basics für Damen, Herren und Kinder – Shirts, Hoodies, Leggings und Freizeitmode mit aktuellem Schnitt.\n\nSF gehört zur Henbury-Gruppe (gegründet 1997) und passt zu Fitnessstudios, Modelabels und Familien-Kollektionen.", "f": ["Fitness", "Mode", "Familien"], "x": {"sitz": "Großbritannien", "gehoert": "Henbury Ltd"}},
  "So Denim": {"t": "So Denim ist die Denim-Linie von AWDis: Jeans, Jeansjacken und Denim-Hemden mit modernen Passformen.\n\nWie alle AWDis-Marken ist So Denim für Veredelung gedacht – ideal für Gastronomie, Handel und Kreativbranche.", "f": ["Gastronomie", "Handel", "Kreativbranche"], "x": {"sitz": "Großbritannien", "gehoert": "AWDis"}},
  "SOL'S": {"t": "SOL'S ist eine französische Marke, gegründet 1991, und eine der großen Marken für Textilveredelung in Europa – 2019 lag der Umsatz bei rund 138,5 Millionen Euro.\n\nDas Sortiment ist riesig: Shirts, Polos, Sweats, Jacken und Workwear in vielen Farben, dazu die Linien SOL'S Teamsport, SOL'S Prowear, SOL'S Bags sowie Neo Blu (Denim) und RTP Apparel (Streetwear).", "f": ["Vereine", "Firmen", "Events"], "x": {"gegruendet": "1991", "sitz": "Frankreich"}},
  "Splashmacs": {"t": "Splashmacs ist auf Regenschutz spezialisiert – Ponchos, Regenjacken und Überzieher für Events und Outdoor.\n\nDie Marke gehört zur Henbury-Gruppe (gegründet 1997). Mit Logo bedruckt ist Splashmacs ideal für Festivals, Sportevents und Outdoor-Aktionen.", "f": ["Festivals", "Events", "Outdoor"], "x": {"sitz": "Großbritannien", "gehoert": "Henbury Ltd"}},
  "Starworld": {"t": "Starworld bietet preiswerte Basics für Promotion und Events – T-Shirts, Sweats und Accessoires für größere Auflagen.\n\nGern stellen wir Ihnen die aktuellen Modelle zusammen.", "f": ["Promotion", "Events", "Großauflagen"], "x": {}},
  "Stedman": {"t": "Stedman geht auf die 1953 in Asheboro (North Carolina, USA) gegründete Stedman Manufacturing Company zurück. In Europa ist die Marke seit 2001 aktiv; die Zentrale sitzt in Aachen, das Hauptlager in Gent (Belgien). Stedman ist in rund 40 Ländern präsent und gehört seit November 2023 zu Next Level Apparel.\n\nSeit dem Relaunch 2025 kommen die T-Shirts, Polos und Sweats mit etikettfreiem Kragen – praktisch für Druck und Umlabeln.", "f": ["Firmen", "Vereine", "Events"], "x": {"gegruendet": "1953", "sitz": "Aachen, Deutschland", "gehoert": "Next Level Apparel"}},
  "Tee Jays": {"t": "Tee Jays wurde 1976 in Florence (Alabama, USA) gegründet; 1979 kam die Marke nach Europa, 2003 entstand TEE JAYS Europe. Seit 2016 betreibt das Unternehmen ein Logistikzentrum in Svenstrup (Dänemark) und gehört heute ganz Peter Hofler.\n\nTee Jays verbindet skandinavisches Design mit hoher Qualität: Polos, Shirts, Strick, Hemden und Jacken mit eleganter Note – ideal für Firmenbekleidung, Golf und Hotel.", "f": ["Firmenbekleidung", "Golf", "Hotel"], "x": {"gegruendet": "1976", "sitz": "Dänemark"}},
  "Terrax Workwear": {"t": "Terrax Workwear liefert robuste Arbeitskleidung für Bau, Handwerk und Industrie – Hosen, Latzhosen, Jacken, Softshells und Westen mit durchdachten Taschen und verstärkten Bereichen.\n\nDie Kollektion ist auch im Baumarkt-Fachhandel bekannt. Mit Stick oder Transferdruck erhalten Handwerksbetriebe ein einheitliches, professionelles Team-Outfit.", "f": ["Bau", "Handwerk", "Industrie"], "x": {}},
  "The One Towelling": {"t": "The One Towelling ist auf Frottierwaren spezialisiert: Handtücher, Gästetücher, Bademäntel und Strandtücher in vielen Farben und Größen.\n\nMit Stick oder Bordüre werden die Tücher zu Werbeträgern für Hotels, Fitnessstudios, Vereine und Kundengeschenke.", "f": ["Hotels", "Fitnessstudios", "Kundengeschenke"], "x": {}},
  "Tiger Cotton": {"t": "Tiger Cotton ist eine Linie von Neutral aus Kopenhagen und bietet zertifizierte Bio-Baumwolle zum guten Preis – nachhaltige Basics für größere Auflagen.\n\nWie Neutral wird Tiger Cotton nach strengen Standards produziert. Ideal für Teams, Events und öffentliche Auftraggeber.", "f": ["Nachhaltige Teams", "Events", "Öffentliche Auftraggeber"], "x": {"sitz": "Kopenhagen, Dänemark", "gehoert": "Neutral"}},
  "Tombo": {"t": "Tombo ist die Marke für Sport- und Teamaccessoires: Taschen, Caps, Stirnbänder, Handschuhe und Trainingsbekleidung.\n\nTombo gehört zur Henbury-Gruppe (gegründet 1997) und passt zu Sportvereinen, Schulen und Fitnessstudios.", "f": ["Sportvereine", "Schulen", "Fitness"], "x": {"sitz": "Großbritannien", "gehoert": "Henbury Ltd"}},
  "Towel City": {"t": "Towel City bietet Handtücher, Bademäntel und Frottierwaren in verlässlicher Qualität und vielen Farben – ideal zum Besticken mit Logo oder Namen.\n\nDie Marke gehört zur Henbury-Gruppe (gegründet 1997) und eignet sich für Hotels, Vereine und Geschenke.", "f": ["Hotels", "Vereine", "Geschenke"], "x": {"sitz": "Großbritannien", "gehoert": "Henbury Ltd"}},
  "TriDri": {"t": "TriDri ist die Performance-Marke für Fitness und Sport: leichte, schnell trocknende Shirts, Tops, Hoodies und Leggings mit modernem Athleisure-Look.\n\nIdeal für Fitnessstudios, Laufgruppen, Personal Trainer und Sportevents.", "f": ["Fitnessstudios", "Laufgruppen", "Personal Trainer"], "x": {}},
  "Tyto": {"t": "Tyto ergänzt das Sortiment um ausgewählte Accessoires mit handwerklicher Note.\n\nWir beraten Sie gern zu den aktuellen Modellen und zur passenden Veredelung.", "f": ["Geschenke", "Accessoires", "Merch"], "x": {}},
  "Utopic": {"t": "Utopic steht für modische Textilien mit klarem Design.\n\nDas aktuelle Sortiment stellen wir Ihnen gern auf Anfrage zusammen – inklusive Beratung zu Druck und Stick.", "f": ["Merch", "Mode", "Teams"], "x": {}},
  "Vossen": {"t": "Vossen wurde 1925 von Burghardt Vossen in Gütersloh gegründet – mit sechs Mitarbeitern. Heute sitzt das Unternehmen in Jennersdorf im Burgenland (Österreich), wo die Frottierwaren gewebt und gefärbt werden; ein Vertriebsbüro ist in Bielefeld. 2017 arbeiteten rund 160 Menschen für Vossen. Seit 2004 gehört Vossen zur Linz Textil AG.\n\nVossen zählt zu den führenden Frottiermarken Europas – Handtücher und Bademäntel in Premium-Qualität. Mit Stick ein besonders wertiges Geschenk.", "f": ["Hotels", "Spa", "Premium-Geschenke"], "x": {"gegruendet": "1925", "sitz": "Jennersdorf, Österreich", "mitarbeiter": "ca. 160 (2017)", "gehoert": "Linz Textil AG"}},
  "Westford Mill": {"t": "Westford Mill ist der Spezialist von Beechfield Brands für Baumwolltaschen, Jutebeutel und Shopper – auch in Bio- und Fairtrade-Qualität.\n\nBeechfield Brands wurde 1995 gegründet und spendet als Mitglied von „1% for the Planet“ ein Prozent des Jahresumsatzes an Umweltprojekte. Ideal für Messen, Einzelhandel und nachhaltige Werbung.", "f": ["Messen", "Einzelhandel", "Nachhaltige Werbung"], "x": {"gegruendet": "1995 (Beechfield Brands)", "sitz": "Großbritannien", "gehoert": "Beechfield Brands"}},
  "Wombat": {"t": "Wombat bietet Taschen und Rucksäcke für Alltag, Schule und Reise – robust und gut zu bedrucken.\n\nIdeal für Schulen, Mitarbeiter-Ausstattung und Reiseanbieter.", "f": ["Schulen", "Mitarbeiter", "Reisen"], "x": {}},
  "X.O by Promodoro": {"t": "X.O ist die Modelinie von Promodoro mit frischen Farben, taillierten Schnitten und einem besonders weichen Jersey, den Promodoro „Millennial Jersey“ nennt.\n\nPromodoro wurde 1989 von Martin Keller gegründet und hat seitdem über 90 Millionen Textilien verkauft.", "f": ["Merch", "Mode", "Jugendteams"], "x": {"gegruendet": "1989 (Promodoro)", "sitz": "Deutschland", "gehoert": "Promodoro"}},
  "Xpres": {"t": "Xpres stammt aus Castle Donington (Großbritannien) und ist seit den 1980er-Jahren auf Sublimation spezialisiert. Die Textilien sind aus Polyester und für vollflächigen Sublimationsdruck gemacht – brillante Fotomotive auf Sportshirts, Taschen und Accessoires.\n\nXpres gehört zur Charterhouse Holdings, zu der auch Kustom Kit gehört.", "f": ["Sublimationsdruck", "Sporttrikots", "Fotomotive"], "x": {"sitz": "Castle Donington, Großbritannien", "gehoert": "Charterhouse Holdings"}},
  "Yoko": {"t": "Yoko ist eine britische Marke für Warnschutzkleidung: Westen, Jacken, Polos und Hosen nach gängigen Normen, gut sichtbar und mit Platz für Ihr Logo.\n\nIdeal für Bau, Logistik, Sicherheitsdienste und Veranstaltungen.", "f": ["Bau", "Logistik", "Sicherheitsdienste"], "x": {"sitz": "Großbritannien"}},
};
export const brandText = (name: string) => BRAND_TEXTS[name] ?? null;
/** erster Absatz – für Meta-Beschreibung */
export const brandTeaser = (name: string) => BRAND_TEXTS[name]?.t.split('\n\n')[0] ?? null;
